package cn.sixnine.filmlog;
import android.app.Instrumentation;
import android.content.Context;
import android.os.Bundle;
import android.os.SystemClock;

public final class TimerRecoveryInstrumentation extends Instrumentation {
    private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    private TimerState finished(Context c){TimerState state=new TimerState();state.start(1000,Math.max(0,SystemClock.elapsedRealtime()-2000),ExposureClock.boot(c));ExposureClock.save(c,state);return state;}
    @Override public void onStart(){waitForIdleSync();Bundle result=new Bundle();try{Context c=getTargetContext();check(c.getPackageName().equals("cn.sixnine.filmlog.media.tests"),"isolated timer test");c.getSharedPreferences("exposure-clock",0).edit().clear().commit();check(!ExposureClock.needsService(c),"idle doesn't start service");
        ExposureTimerService service=new ExposureTimerService();java.lang.reflect.Method attach=android.content.ContextWrapper.class.getDeclaredMethod("attachBaseContext",android.content.Context.class);attach.setAccessible(true);attach.invoke(service,c);java.lang.reflect.Method notice=ExposureTimerService.class.getDeclaredMethod("notice",String.class,boolean.class);notice.setAccessible(true);for(boolean done:new boolean[]{false,true})check(((android.app.Notification)notice.invoke(service,"icon check",done)).getSmallIcon().getResId()==R.drawable.brand_notification,"running/completed notification brand icon");
        ExposureTimerService.channels(c);android.app.NotificationManager notifications=c.getSystemService(android.app.NotificationManager.class);check(notifications.getNotificationChannel(ExposureTimerService.CHANNEL).getImportance()==android.app.NotificationManager.IMPORTANCE_LOW,"running channel stays quiet");check(notifications.getNotificationChannel(ExposureTimerService.COMPLETION_CHANNEL).getImportance()==android.app.NotificationManager.IMPORTANCE_HIGH,"completion uses distinct alert channel");ExposureClock.begin(c,60000);check(ExposureClock.needsService(c),"running resumes service");ExposureClock.acknowledgeCompletion(c);check(ExposureClock.read(c).status.equals("running"),"acknowledgment never clears a running timer");ExposureClock.pause(c);ExposureClock.acknowledgeCompletion(c);check(ExposureClock.read(c).status.equals("paused"),"acknowledgment never clears a paused timer");check(!ExposureClock.needsService(c),"paused remains paused");ExposureClock.cancel(c);check(!ExposureClock.needsService(c),"cancelled not restarted");
        finished(c);check(ExposureClock.read(c).status.equals("finished"),"elapsed deadline finished before service restart");check(ExposureClock.needsService(c),"finished unalerted deadline still needs completion");check(ExposureClock.claimCompletion(c),"first completion claims alert");check(!ExposureClock.claimCompletion(c)&&!ExposureClock.needsService(c),"completed alert not replayed");
        TimerState priorBoot=finished(c);priorBoot.status="finished";priorBoot.boot=ExposureClock.boot(c)-1;ExposureClock.save(c,priorBoot);check(!ExposureClock.needsService(c)&&!ExposureClock.claimCompletion(c),"past boot completion never replayed");
        TimerState interrupted=finished(c);interrupted.boot=ExposureClock.boot(c)-1;ExposureClock.save(c,interrupted);check(ExposureClock.read(c).status.equals("interrupted")&&!ExposureClock.needsService(c),"reboot interrupts running deadline");
        c.getSharedPreferences("exposure-clock",0).edit().clear().commit();finished(c);ExposureClock.read(c);ExposureClock.cancel(c);check(!ExposureClock.claimCompletion(c)&&!ExposureClock.needsService(c),"cancel after deadline suppresses late alert");finished(c);ExposureClock.read(c);ExposureClock.acknowledgeCompletion(c);check(ExposureClock.read(c).status.equals("idle")&&!ExposureClock.needsService(c)&&!ExposureClock.claimCompletion(c),"explicit completion acknowledgment returns to ready and prevents late alert");ExposureClock.begin(c,60000);check(ExposureClock.read(c).status.equals("running"),"new timer can start after acknowledgment");c.getSharedPreferences("exposure-clock",0).edit().clear().commit();result.putString("stream","PASS: separate quiet/alert notification channels; running resumes; pause/cancel stay stopped; expired before recovery claims completion once; already alerted and prior boot not replayed; acknowledgment preserves active timers and enables a new timer\n");finish(-1,result);
    }catch(Throwable failure){result.putString("stream",android.util.Log.getStackTraceString(failure));finish(0,result);}}
}
